                alpha = (unsigned char)((dist - 0.4f) * 1274.9998779296875f);
            NGraphicAppearance::CTCGraphicAppearance* tc;
            if (creature->GetTC(TCI_GRAPHIC_APPEARANCE_NEW, &tc))
                tc->SetAlpha(alpha);
