            if (GFRandom(2, GetPWorldSeed()) == 0)
                return Laugh();
            if (GFRandom(2, GetPWorldSeed()) == 0)
                return SitIdle();
            return TellStory();
        }
        else {
            if (GFRandom(2, GetPWorldSeed()) == 0)
                return SitIdle();
            return TellStory();
        }
        return result;
    }
    switch (GFRandom(5, GetPWorldSeed())) {
    case 1:
        return FallAsleep();
    case 0:
        if (IS_THING_ALIVE(PTankard))
            return Drink();
    default:
        return SitIdle();
    }
}

